corrected_code:
package auditing

import (
	"context"
	"errors"
	"gorm.io/gorm"
	"myapp/auth"
	"myapp/models"
)

type AuditRepository struct {
	DB *gorm.DB
}

func (r *AuditRepository) QuerySecurityLogs(ctx context.Context, category string, targetOrgID uint) ([]models.AuditLog, error) {
	callerOrgID := auth.CallerOrgID(ctx)
	if callerOrgID != targetOrgID {
		return nil, errors.New("access denied to target organization audit logs")
	}

	var logs []models.AuditLog
	err := r.DB.WithContext(ctx).
		Where("category = ? AND organization_id = ?", category, callerOrgID).
		Find(&logs).Error
	if err != nil {
		return nil, err
	}
	return logs, nil
}
